#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

NACOS_CONTAINER="${NACOS_CONTAINER:-nacos-standalone-derby}"
EXPECTED_HOST="${EXPECTED_HOST:-luykin-crawler-server}"
RUN_ID=$(date -u +%Y%m%dT%H%M%SZ)
BACKUP_ROOT="/root/luykin-storage-guard-backups/$RUN_ID"

ask_default() {
  local variable="$1" prompt="$2" default_value="$3" input=""
  printf '  %s%s%s %s[default: %s]%s ' \
    "$BOLD" "$prompt" "$RESET" "$DIM" "$default_value" "$RESET"
  read -r input || true
  printf -v "$variable" '%s' "${input:-$default_value}"
}

require_command() {
  if ! command -v "$1" >/dev/null 2>&1; then
    printf 'Missing required command: %s\n' "$1" >&2
    exit 1
  fi
}

restore_file() {
  local target="$1" backup="$2" existed="$3"
  if [[ "$existed" == "1" ]]; then
    cp -a "$backup" "$target"
  else
    rm -f -- "$target"
  fi
}

banner "Production storage guard"

stage "Preflight and protected backup directory"
say "This wizard changes only Nacos log retention, Docker log defaults, Nginx access logging, and journald limits."
warn "It does not delete current logs, rebuild containers, deploy code, or alter database data."
if [[ ${EUID:-$(id -u)} -ne 0 ]]; then
  say "Run this wizard as root: sudo bash scripts/storage-guard-wizard.sh"
  exit 1
fi
for command_name in docker python3 nginx systemctl systemd-analyze journalctl install cp grep; do
  require_command "$command_name"
done
CURRENT_HOST=$(hostname)
say "Current host: $CURRENT_HOST"
if [[ "$CURRENT_HOST" != "$EXPECTED_HOST" ]]; then
  warn "Expected host '$EXPECTED_HOST', but this is '$CURRENT_HOST'."
  if ! confirm "Continue on this host anyway?"; then
    exit 0
  fi
fi
docker inspect "$NACOS_CONTAINER" >/dev/null
df -h /
if ! confirm "Create a protected backup directory and continue?"; then
  exit 0
fi
install -d -m 0700 "$BACKUP_ROOT"
say "Rollback copies will be kept in: $BACKUP_ROOT"
pause "Press Enter for Nacos settings."

stage "Nacos access-log retention"
CURRENT_NACOS_DAYS=$(docker exec "$NACOS_CONTAINER" sh -c \
  "sed -n 's/^server.tomcat.accesslog.max-days=//p' /home/nacos/conf/application.properties" | tail -n1)
say "Current Nacos access-log retention: ${CURRENT_NACOS_DAYS:-unknown} days"
ask_default NACOS_DAYS "Choose the new retention (7 or 14 days):" "14"
if [[ "$NACOS_DAYS" != "7" && "$NACOS_DAYS" != "14" ]]; then
  say "Only 7 or 14 is accepted. No Nacos change was made."
  exit 1
fi
if [[ "$CURRENT_NACOS_DAYS" == "$NACOS_DAYS" ]]; then
  say "Nacos is already configured for $NACOS_DAYS days; skipping the write."
else
  warn "This container has no config volume. The change survives restart, but must be reapplied if the container is recreated."
  if confirm "Back up and update Nacos retention to $NACOS_DAYS days?"; then
    NACOS_BACKUP="$BACKUP_ROOT/nacos-application.properties"
    NACOS_CANDIDATE="$BACKUP_ROOT/nacos-application.properties.candidate"
    docker cp "$NACOS_CONTAINER:/home/nacos/conf/application.properties" "$NACOS_BACKUP" >/dev/null
    cp -a "$NACOS_BACKUP" "$NACOS_CANDIDATE"
    python3 - "$NACOS_CANDIDATE" "$NACOS_DAYS" <<'PY'
import pathlib
import re
import sys

path = pathlib.Path(sys.argv[1])
days = sys.argv[2]
text = path.read_text()
pattern = r"(?m)^server\.tomcat\.accesslog\.max-days=.*$"
if len(re.findall(pattern, text)) != 1:
    raise SystemExit("Expected exactly one server.tomcat.accesslog.max-days property")
path.write_text(re.sub(pattern, f"server.tomcat.accesslog.max-days={days}", text, count=1))
PY
    docker cp "$NACOS_CANDIDATE" "$NACOS_CONTAINER:/home/nacos/conf/application.properties" >/dev/null
    rm -f -- "$NACOS_CANDIDATE"
    if ! APPLIED_NACOS_DAYS=$(docker exec "$NACOS_CONTAINER" sh -c \
      "sed -n 's/^server.tomcat.accesslog.max-days=//p' /home/nacos/conf/application.properties" | tail -n1); then
      docker cp "$NACOS_BACKUP" "$NACOS_CONTAINER:/home/nacos/conf/application.properties" >/dev/null || true
      say "Nacos verification could not run; the original file was restored."
      exit 1
    fi
    if [[ "$APPLIED_NACOS_DAYS" != "$NACOS_DAYS" ]]; then
      docker cp "$NACOS_BACKUP" "$NACOS_CONTAINER:/home/nacos/conf/application.properties" >/dev/null
      say "Nacos verification failed; the original file was restored."
      exit 1
    fi
    say "Nacos configuration updated. Backup: $NACOS_BACKUP"
    if confirm "Restart only the Nacos container now to apply it?"; then
      if ! docker restart "$NACOS_CONTAINER" >/dev/null; then
        docker cp "$NACOS_BACKUP" "$NACOS_CONTAINER:/home/nacos/conf/application.properties" >/dev/null
        docker restart "$NACOS_CONTAINER" >/dev/null || true
        say "Nacos restart failed; the original configuration was restored."
        exit 1
      fi
      sleep 5
      if [[ "$(docker inspect --format='{{.State.Running}}' "$NACOS_CONTAINER")" != "true" ]]; then
        docker cp "$NACOS_BACKUP" "$NACOS_CONTAINER:/home/nacos/conf/application.properties" >/dev/null
        docker restart "$NACOS_CONTAINER" >/dev/null || true
        say "Nacos did not remain running; the original configuration was restored."
        exit 1
      fi
      say "Nacos container is running with the new setting."
    else
      SKIPPED+=("Restart $NACOS_CONTAINER during a maintenance window to apply the new retention")
    fi
  else
    SKIPPED+=("Nacos access-log retention")
  fi
fi
pause "Press Enter for Docker log defaults."

stage "Docker json-file rotation defaults"
ask_default DOCKER_LOG_SIZE "Maximum size of one container log file:" "100m"
ask_default DOCKER_LOG_FILES "Maximum rotated files per container:" "5"
if [[ ! "$DOCKER_LOG_SIZE" =~ ^[1-9][0-9]*[kKmMgG]$ ]]; then
  say "Invalid size '$DOCKER_LOG_SIZE' (examples: 50m, 100m, 1g)."
  exit 1
fi
if [[ ! "$DOCKER_LOG_FILES" =~ ^[1-9][0-9]*$ ]]; then
  say "Invalid file count '$DOCKER_LOG_FILES'."
  exit 1
fi
warn "Docker default log options affect newly created containers only. Existing containers are not recreated by this wizard."
if confirm "Merge these Docker defaults into /etc/docker/daemon.json?"; then
  DOCKER_CONFIG=/etc/docker/daemon.json
  DOCKER_EXISTED=0
  DOCKER_BACKUP="$BACKUP_ROOT/docker-daemon.json"
  if [[ -f "$DOCKER_CONFIG" ]]; then
    DOCKER_EXISTED=1
    cp -a "$DOCKER_CONFIG" "$DOCKER_BACKUP"
  fi
  DOCKER_CANDIDATE="$BACKUP_ROOT/docker-daemon.json.candidate"
  python3 - "$DOCKER_CONFIG" "$DOCKER_CANDIDATE" "$DOCKER_LOG_SIZE" "$DOCKER_LOG_FILES" <<'PY'
import json
import pathlib
import sys

source = pathlib.Path(sys.argv[1])
target = pathlib.Path(sys.argv[2])
config = json.loads(source.read_text()) if source.exists() else {}
if not isinstance(config, dict):
    raise SystemExit("Docker daemon.json must contain a JSON object")
config["log-driver"] = "json-file"
log_opts = config.setdefault("log-opts", {})
if not isinstance(log_opts, dict):
    raise SystemExit("Docker log-opts must be a JSON object")
log_opts.update({
    "max-size": sys.argv[3].lower(),
    "max-file": sys.argv[4],
    "compress": "true",
})
target.write_text(json.dumps(config, ensure_ascii=False, indent=2) + "\n")
PY
  if command -v dockerd >/dev/null 2>&1; then
    dockerd --validate --config-file "$DOCKER_CANDIDATE"
  else
    warn "dockerd is unavailable; only JSON syntax was validated."
  fi
  install -m 0644 "$DOCKER_CANDIDATE" "$DOCKER_CONFIG"
  say "Docker config installed; rollback copy: ${DOCKER_BACKUP:-file did not previously exist}"
  if confirm "Reload Docker now (running containers stay running)?"; then
    if ! systemctl reload docker; then
      restore_file "$DOCKER_CONFIG" "$DOCKER_BACKUP" "$DOCKER_EXISTED"
      systemctl reload docker || true
      say "Docker reload failed; the original daemon config was restored."
      exit 1
    fi
    say "Docker reloaded. New containers will use the size limits."
  else
    SKIPPED+=("Reload Docker to activate defaults for newly created containers")
  fi
  SKIPPED+=("Recreate existing containers during their normal maintenance window to inherit Docker log limits")
else
  SKIPPED+=("Docker json-file rotation defaults")
fi
pause "Press Enter for Nginx logging."

stage "Nginx: do not record OPTIONS"
NGINX_CONFIG=/etc/nginx/nginx.conf
NGINX_SITE=/etc/nginx/sites-available/kb.cryptohunt.ai
say "The wizard will add an http-level request-method map and condition the main access log."
if confirm "Back up, patch, validate, and reload Nginx?"; then
  NGINX_BACKUP="$BACKUP_ROOT/nginx.conf"
  NGINX_CANDIDATE="$BACKUP_ROOT/nginx.conf.candidate"
  cp -a "$NGINX_CONFIG" "$NGINX_BACKUP"
  cp -a "$NGINX_CONFIG" "$NGINX_CANDIDATE"
  python3 - "$NGINX_CANDIDATE" <<'PY'
import pathlib
import sys

path = pathlib.Path(sys.argv[1])
text = path.read_text()
map_marker = "map $request_method $access_log_enabled"
map_block = (
    "\n    # OPTIONS preflight requests are intentionally excluded from access logs.\n"
    "    map $request_method $access_log_enabled {\n"
    "        default 1;\n"
    "        OPTIONS 0;\n"
    "    }\n"
)
if map_marker not in text:
    if text.count("http {") != 1:
        raise SystemExit("Expected exactly one http block")
    text = text.replace("http {", "http {" + map_block, 1)
old = "access_log /var/log/nginx/access.log main;"
new = "access_log /var/log/nginx/access.log main if=$access_log_enabled;"
if new not in text:
    if text.count(old) != 1:
        raise SystemExit("Expected exactly one main access_log directive")
    text = text.replace(old, new, 1)
path.write_text(text)
PY

  NGINX_SITE_EXISTED=0
  NGINX_SITE_BACKUP="$BACKUP_ROOT/kb.cryptohunt.ai.conf"
  if [[ -f "$NGINX_SITE" ]]; then
    NGINX_SITE_EXISTED=1
    NGINX_SITE_CANDIDATE="$BACKUP_ROOT/kb.cryptohunt.ai.conf.candidate"
    cp -a "$NGINX_SITE" "$NGINX_SITE_BACKUP"
    cp -a "$NGINX_SITE" "$NGINX_SITE_CANDIDATE"
    python3 - "$NGINX_SITE_CANDIDATE" <<'PY'
import pathlib
import re
import sys

path = pathlib.Path(sys.argv[1])
text = path.read_text()
if "access_log /var/log/nginx/sse_error_access.log if=$access_log_enabled;" not in text:
    pattern = r"(?m)^(\s*)access_log\s+/var/log/nginx/sse_error_access\.log;$"
    text, count = re.subn(
        pattern,
        r"\1access_log /var/log/nginx/sse_error_access.log if=$access_log_enabled;",
        text,
        count=1,
    )
    if count != 1:
        raise SystemExit("Expected one sse_error_access.log directive")
path.write_text(text)
PY
  fi

  cp -a "$NGINX_CANDIDATE" "$NGINX_CONFIG"
  if [[ "$NGINX_SITE_EXISTED" == "1" ]]; then
    if ! cp -a "$NGINX_SITE_CANDIDATE" "$NGINX_SITE"; then
      cp -a "$NGINX_BACKUP" "$NGINX_CONFIG"
      say "Could not install the Nginx site candidate; the original main config was restored."
      exit 1
    fi
  fi

  if ! nginx -t; then
    cp -a "$NGINX_BACKUP" "$NGINX_CONFIG"
    restore_file "$NGINX_SITE" "$NGINX_SITE_BACKUP" "$NGINX_SITE_EXISTED"
    say "Nginx validation failed; all original files were restored."
    exit 1
  fi
  if ! systemctl reload nginx; then
    cp -a "$NGINX_BACKUP" "$NGINX_CONFIG"
    restore_file "$NGINX_SITE" "$NGINX_SITE_BACKUP" "$NGINX_SITE_EXISTED"
    nginx -t && systemctl reload nginx || true
    say "Nginx reload failed; all original files were restored."
    exit 1
  fi
  say "Nginx reloaded successfully; OPTIONS requests are no longer written to these access logs."
else
  SKIPPED+=("Nginx OPTIONS access-log exclusion")
fi
pause "Press Enter for journald limits."

stage "journald persistent storage cap"
JOURNAL_DIR=/etc/systemd/journald.conf.d
JOURNAL_CONFIG="$JOURNAL_DIR/90-luykin-storage-limit.conf"
JOURNAL_EXISTED=0
JOURNAL_BACKUP="$BACKUP_ROOT/journald-storage-limit.conf"
say "Target: SystemMaxUse=1G. Existing journal files are not manually vacuumed."
if confirm "Install the 1GiB journald cap and restart systemd-journald?"; then
  install -d -m 0755 "$JOURNAL_DIR"
  if [[ -f "$JOURNAL_CONFIG" ]]; then
    JOURNAL_EXISTED=1
    cp -a "$JOURNAL_CONFIG" "$JOURNAL_BACKUP"
  fi
  JOURNAL_CANDIDATE="$BACKUP_ROOT/journald-storage-limit.conf.candidate"
  printf '%s\n' '[Journal]' 'SystemMaxUse=1G' > "$JOURNAL_CANDIDATE"
  install -m 0644 "$JOURNAL_CANDIDATE" "$JOURNAL_CONFIG"
  if ! systemd-analyze cat-config systemd/journald.conf | grep -qE '^SystemMaxUse=1G$'; then
    restore_file "$JOURNAL_CONFIG" "$JOURNAL_BACKUP" "$JOURNAL_EXISTED"
    say "journald did not recognize the candidate; the original config was restored."
    exit 1
  fi
  if ! systemctl restart systemd-journald; then
    restore_file "$JOURNAL_CONFIG" "$JOURNAL_BACKUP" "$JOURNAL_EXISTED"
    systemctl restart systemd-journald || true
    say "journald restart failed; the original config was restored."
    exit 1
  fi
  if ! systemctl is-active --quiet systemd-journald; then
    restore_file "$JOURNAL_CONFIG" "$JOURNAL_BACKUP" "$JOURNAL_EXISTED"
    systemctl restart systemd-journald || true
    say "journald is not active; the original config was restored."
    exit 1
  fi
  systemd-analyze cat-config systemd/journald.conf | grep -E '^SystemMaxUse=1G$'
  journalctl --disk-usage
  say "journald is active with a 1GiB persistent cap. Old archives are reclaimed by journald during rotation."
else
  SKIPPED+=("journald 1GiB storage cap")
fi

finish
note "Rollback files: $BACKUP_ROOT"
